use dacc_knowledge::{Enforced, InvariantStatus};
use dacc_core::NonEmptyStr;

dacc_knowledge::invariant!("i0030",
    specification: crate::rfc::rfc_2026_003,
    status: InvariantStatus::Enforced(Enforced::Adversarial { bypass: NonEmptyStr::new("A run that starts with nobody attached — the command line letting one through without `--as`, or a caller driving `run::apply` at the engine's door — or a static key reaching the transport through the fleet document. What this entry does not cover: an actor that is a lie. The engine cannot tell a real OIDC subject from a string, and that a name is who it says it is is the grant's claim (0009), not one made here."), tests: &[crate::anchor::a_run_without_an_actor_is_refused_naming_the_flag, crate::anchor::a_run_proceeds_only_with_an_actor_identity, crate::anchor::a_fleet_that_names_a_key_is_refused_naming_it, crate::anchor::no_identity_reaches_the_ssh_command] }),
    statement: NonEmptyStr::new("INV-TRUST-001: No run proceeds without an actor identity; static keys are not a mode."),
    rationale: r"Both halves hold. A run carries who acts — a person over OIDC or Teleport, CI over workload identity, an agent over a grant (0009) — as `--as`, with the scope and expiry a grant will one day check; the actor goes into the plan and its number, so a signature over the number is a signature over somebody's plan, and into a journal beside state for a person reading afterwards. The static-key half is an absence that is now pinned from three sides: the transport's `ssh` invocation is one shape a test reads word by word, the fleet document refuses a `key` field by name because the port, the jump host and the key belong to `ssh`, and no code path reads a long-lived actor key — a key that names who acts, which a deadline cannot produce. A provider's service-account key is a cloud credential, not an identity: the Yandex provider may read one only to sign a single JWT and carry the short-lived token afterwards (075), a flow that is not in the tree until w-yc-credential-model lands. What moved since this was written, added on the review of v0013 and not a rewrite of the above: the expiry does not wait for the grant untouched any more, because the comparison needs no grant to make — an identity whose expiry has passed does not run, and an expiry that is not an RFC3339 time is refused by name. The scope is the half still carried for the grant to check.",
    enforced_by: &[crate::anchor::inv_trust_001],
    tests: &[crate::anchor::a_run_without_an_actor_is_refused_naming_the_flag, crate::anchor::a_run_proceeds_only_with_an_actor_identity, crate::anchor::a_fleet_that_names_a_key_is_refused_naming_it, crate::anchor::no_identity_reaches_the_ssh_command, crate::anchor::whose_plan_it_is_moves_the_number],
);
